Here's a C++ function that takes a reference to a `std::string` containing Markdown formatted text and returns a `std::string` containing HTML formatted text:

```cpp
#include <iostream>
#include <regex>
#include <string>

std::string markdownToHtml(const std::string& markdown) {
    // Replace Markdown links with HTML links
    std::regex re(R"(https?://([^\s]*)[^\s]*)*)");
    std::string html;
    std::regex_replace(markdown, html, re, "<a href='$1'>$1</a>");
    return html;
}

int main() {
    // Example usage
    std::string markdown = "Visit [this](https://example.com) for more info.";
    std::string html = markdownToHtml(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

